    const ledger = new CountingLedger();
    const forwarded = [];
    let calls = 0;
    const service = new PaymentService(ledger, {
      acknowledge: async (r) => {
        forwarded.push(r);
        if (++calls <= 2) throw new Transient('ack down');
      },
    });
    const receipt = await service.pay('shop', 'sale', 123, 3);
    assert.deepEqual(receipt, { id: 1, tenant: 'shop', key: 'sale', cents: 123 });
    assert.equal(calls, 3, 'should use up to attempts tries');
    assert.equal(ledger.entries.length, 1, 'retries must not duplicate the debit');
    assert.equal(ledger.applies, 1, 'a fetched receipt is reused on retries');
    for (const r of forwarded) assert.strictEqual(r, receipt, 'same receipt forwarded each try');
  }

  // --- Retry exhaustion preserves the final exception ---------------------
  {
    const ledger = new Ledger();
    const errors = [new Transient('first'), new Transient('second')];
    let calls = 0;
    const service = new PaymentService(ledger, {
      acknowledge: async () => { throw errors[calls++]; },
    });
    try {
      await service.pay('t', 'k', 5, 2);
      assert.fail('expected failure');
    } catch (e) {
      assert.strictEqual(e, errors[1], 'must throw the final transient');
    }
    assert.equal(calls, 2, 'attempts caps total tries');
    assert.equal(ledger.entries.length, 1, 'debit committed exactly once');
  }

  // --- Non-transient errors are not retried -------------------------------
  {
    const ledger = new Ledger();
    const boom = new Error('boom');
    let calls = 0;
    const service = new PaymentService(ledger, { acknowledge: async () => { calls++; throw boom; } });
    await assert.rejects(service.pay('t', 'k', 5, 5), (e) => e === boom);
    assert.equal(calls, 1, 'non-transient must not be retried');
    assert.equal(ledger.entries.length, 1);
  }

  // --- Transient from apply is retried too --------------------------------
  {
    const real = new Ledger();
    const flaky = {
      calls: 0,
      async apply(tenant, key, cents) {
        if (++this.calls === 1) throw new Transient('ledger hiccup');
        return real.apply(tenant, key, cents);
      },
    };
    const service = new PaymentService(flaky, { acknowledge: async () => {} });
    const receipt = await service.pay('t', 'k', 9, 3);
    assert.equal(receipt.id, 1);
    assert.equal(real.entries.length, 1);
  }

